// ❌ OLD: Synchronous crypto/hashing on the event loop. Every
// request that computes a hash or runs pbkdf2Sync() BLOCKS the entire
// process: no other request, timer, or event is processed until it
// finishes. Under load, one slow sync op freezes all users.
const crypto = require('node:crypto');
const http = require('node:http');

http.createServer((req, res) => {
  const hash = crypto.createHash('sha256').update(req.url).digest('hex');
  // ❌ OLD: runs on the main thread — blocks every other connection
  res.end(hash);
}).listen(3000);

// ✅ NEW: The async crypto APIs offload to the libuv thread pool, so
// the event loop stays free to serve other requests while the hashing
// runs on a worker thread.
const crypto = require('node:crypto');
const http = require('node:http');

http.createServer((req, res) => {
  // ✅ NEW: runs on a libuv worker thread, not the event loop
  crypto.pbkdf2(req.url, 'salt', 100_000, 64, 'sha512', (err, key) => {
    res.end(key.toString('hex'));
  });
}).listen(3000);

